test_code:
def calculate_late_fine(days_late):
    if days_late <= 0: return 0
    if days_late <= 15: return days_late * 100
    return (15 * 100) + ((days_late - 15) * 250)
assert calculate_late_fine(10) == 1000
assert calculate_late_fine(20) == 2750

